import fs from "node:fs/promises";
import { safeJoin } from "@/features/projects/infrastructure/paths";
import type { Project } from "@/features/projects/domain/types";
import { applyTokens } from "@/features/codegen/infrastructure/templates";
import { NODEJS_TEST_CONFIG_CONTENT } from "@/features/architectures/infrastructure/architectureService";
import {
  NODEJS_TEST_CONFIG_REL,
  NODEJS_URL_BLOCK_CLOSE,
  NODEJS_URL_BLOCK_OPEN,
} from "./paths";

/**
 * Rewrite the `<auto-generated-urls>` block inside `shared/testConfig.ts`
 * with one `readonly NAME = process.env["<KEY>"] ?? ""` field per
 * `.env` URL key.
 */
export async function regenerateTestConfig(
  project: Project,
  urlNames: string[],
  solutionName: string,
): Promise<string | null> {
  const abs = safeJoin(project.rootPath, NODEJS_TEST_CONFIG_REL);
  const safeSolution = solutionName
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_");
  const sorted = [...new Set(urlNames)].sort();
  const innerLines = sorted.map(
    (n) => `  readonly ${n} = process.env["${safeSolution}_URL_${n}"] ?? "";`,
  );

  let original: string | null = null;
  try {
    original = await fs.readFile(abs, "utf8");
  } catch {
    // file missing — fall through to template materialization
  }

  if (
    original === null ||
    !original.includes(NODEJS_URL_BLOCK_OPEN) ||
    !original.includes(NODEJS_URL_BLOCK_CLOSE)
  ) {
    const sharedDir = safeJoin(project.rootPath, "shared");
    try {
      await fs.mkdir(sharedDir, { recursive: true });
    } catch {
      return null;
    }
    const rendered = applyTokens(NODEJS_TEST_CONFIG_CONTENT, {
      namespace: project.namespace,
      solution: project.solutionName,
    });
    const seeded = replaceMarkerBlockNodejs(
      rendered,
      NODEJS_URL_BLOCK_OPEN,
      NODEJS_URL_BLOCK_CLOSE,
      innerLines,
    );
    await fs.writeFile(abs, seeded);
    return NODEJS_TEST_CONFIG_REL;
  }

  const next = replaceMarkerBlockNodejs(
    original,
    NODEJS_URL_BLOCK_OPEN,
    NODEJS_URL_BLOCK_CLOSE,
    innerLines,
  );
  if (next === original) return NODEJS_TEST_CONFIG_REL;
  await fs.writeFile(abs, next);
  return NODEJS_TEST_CONFIG_REL;
}

function replaceMarkerBlockNodejs(
  original: string,
  openMarker: string,
  closeMarker: string,
  innerLines: string[],
): string {
  const lines = original.split(/\r?\n/);
  let openIdx = -1;
  let closeIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i]!.includes(openMarker)) {
      openIdx = i;
      for (let j = i + 1; j < lines.length; j++) {
        if (lines[j]!.includes(closeMarker)) {
          closeIdx = j;
          break;
        }
      }
      break;
    }
  }
  if (openIdx === -1 || closeIdx === -1) return original;
  const next = [
    ...lines.slice(0, openIdx + 1),
    ...innerLines,
    ...lines.slice(closeIdx),
  ];
  return next.join("\n");
}
